import { ArkErrors, scope, type } from "arktype";

/**
 * Node schema:
 * - id:       a non-negative integer
 * - label:    a string whose length is between 1 and 40 (inclusive)
 * - edges:    an array of Node (self-referential; supports cycles)
 *
 * Graph schema:
 * - rootId:   a non-negative integer
 * - nodes:    an array of Node with length between 1 and 1000 (inclusive)
 *
 * Cross-node structural constraints are enforced via .narrow() on the
 * Graph type:
 * 1. all `nodes[*].id` values are unique;
 * 2. every edge target's `id` exists in `nodes`;
 * 3. `rootId` is one of `nodes[*].id`.
 */
const graphScope = scope({
	Node: {
		id: "number >= 0",
		label: "1 <= string <= 40",
		edges: "Node[]"
	}
});

const Graph = graphScope
	.type({
		rootId: "number >= 0",
		nodes: "1 <= Node[] <= 1000"
	})
	.narrow((value, ctx) => {
		const seenIds = new Set<number>();
		for (const node of value.nodes) {
			if (seenIds.has(node.id)) {
				return ctx.mustBe("node ids must be unique");
			}
			seenIds.add(node.id);
		}
		if (!seenIds.has(value.rootId)) {
			return ctx.mustBe("rootId must match a node id");
		}
		for (const node of value.nodes) {
			for (const edge of node.edges) {
				if (!seenIds.has(edge.id)) {
					return ctx.mustBe("edge target must be a node id");
				}
			}
		}
		return true;
	});

export type Node = typeof graphScope.export().Node.infer;
export type Graph = typeof Graph.infer;

/**
 * Validate that `input` is a structurally well-formed Graph.
 *
 * @throws {Error} when `input` does not satisfy the schema.
 * @returns the validated Graph on success.
 */
export function validateGraph(input: unknown): Graph {
	const result = Graph(input);
	if (result instanceof ArkErrors) {
		throw new Error(result.summary);
	}
	return result as Graph;
}

export const graphValidator = Graph;

