	if (payload === null || typeof payload !== "object") {
		throw new Error("input payload must be a JSON object");
	}
	const obj = payload as Record<string, unknown>;
	if (!("graph" in obj)) {
		throw new Error("input payload must contain a `graph` property");
	}
	return obj.graph;
}

